def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find mirror row (containing 2s)
    mirror_row = None
    for r in range(h):
        if any(grid[r][c] == 2 for c in range(w)):
            mirror_row = r
            break

    result = [[0]*w for _ in range(h)]
    for c in range(w):
        result[mirror_row][c] = 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                inp_dist = abs(r - mirror_row)
                if r < mirror_row:
                    out_r = mirror_row - inp_dist + 1
                else:
                    out_r = mirror_row + 1
                if 0 <= out_r < h and out_r != mirror_row:
                    result[out_r][c] = 4

    return result

